#!/usr/bin/env python3
import argparse,fcntl,hashlib,json,importlib.util
from pathlib import Path
def main():
 p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);p.add_argument('--passed-report',type=Path,required=True);a=p.parse_args();root=a.root;project=root/'project';lock=(root/'native.lock').open('a');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB);v=json.loads(a.passed_report.read_text());assert v['passed'] and v['phase']=='v1';meta=json.loads((root/'grade.json').read_text());evidence=json.loads(Path(str(a.passed_report).removesuffix('-result.json')+'-native-evidence.json').read_text());meta['passed_v1_release']=evidence['status']['release'];spec=importlib.util.spec_from_file_location('level8_grade',Path(__file__).with_name('level8-grade.py'));g=importlib.util.module_from_spec(spec);spec.loader.exec_module(g);snapshot=g.call(root,{'op':'capture-v1','checkpoint_id':json.loads((project/'CHECKPOINT.json').read_text())['workflow_id']});baseline=root/'project/UPGRADE-BASELINE.json';baseline.write_text(json.dumps({'rollback_release':meta['passed_v1_release'],'v1_snapshot':snapshot},indent=2));meta['protected']['UPGRADE-BASELINE.json']=hashlib.sha256(baseline.read_bytes()).hexdigest();assert not (project/'CHANGE.md').exists();assert hashlib.sha256((project/'CHECKPOINT.json').read_bytes()).hexdigest()==meta['checkpoint_sha256'];(project/'CHANGE.md').write_bytes((Path(__file__).parent/'level8-lab/CHANGE.md').read_bytes());meta['protected']['CHANGE.md']=hashlib.sha256((project/'CHANGE.md').read_bytes()).hexdigest();(root/'grade.json').write_text(json.dumps(meta,indent=2));print('{"turn_b_ready":true}')
if __name__=='__main__':main()
